function verif1() {
  const h = document.getElementById("homme").checked;
  const f = document.getElementById("femme").checked;
  const np = document.getElementById("np").value;
  const tel = document.getElementById("tel").value;
  const naissance = document.getElementById("naissance").value;
  const gouvernaurat = document.getElementById("gouvernaurat").value;
  const mail = document.getElementById("mail").value;
  const psw = document.getElementById("psw").value;
  const cpsw = document.getElementById("cpsw").value;
  const conditions = document.getElementById("conditions").checked;
  //------------------------------------------------------
  //sexe:choix obligatoire
  if (!f & !h) {
    alert("Veuillez choisir le sexe!!");
    return false;
  }
  //---------------------------------------------------------------
  /*Nom & Prénom:Chaine alphabétique contenant au minimum un espace 
    et de taille minimale 5 caractères.*/
  /*Remarque : puisque on veut que la chaine doit contenir au minimum un espace on doit tester sur son index au début dans les contrôles et aussi la mettre dans notre fonction alpha*/
  if (np.length < 5 || !alpha(np) || np.indexOf(" ") == -1) {
    alert("Vérifier votre nom et prénom!!");
    return false;
  }
  //---------------------------------------------------------------
  //tel:numérique de taille 8
  if (tel.length != 8 || !numerique(tel)) {
    alert("Vérifier votre numéro téléphone!!");
    return false;
  }
  //---------------------------------------------------------------
  //date:choix obligatoire
  if (naissance == "") {
    alert("Vérifier le choix de votre date de naissance !!");
    return false;
  }
  //gouvernorat : choix obligatoire
  if (gouvernaurat == "") {
    alert("Vérifier le choix de votre gouvernorat !!");
    return false;
  }

  const posat = mail.indexOf("@");
  const pospt = mail.indexOf(".");
  if (posat == -1 || pospt == -1 || pospt < posat) {
    alert("mail invalid");
    return false;
  }
  const ch1 = substr(0, posat);
  const ch2 = substr(posat + 1, pospt - posat - 1);
  const ch3 = substr(pospt + 1);
  if (!alpha1(ch3)) {
    alert("mail invalide");
    return false;
  }

  if (ch1 == "" || ch2 == "" || ch3 == "" || ch3.length < 2 || ch3.length > 3) {
    alert("Vérifier votre mail SVP");
    return false;
  }

  if (!alphanumerique(ch1) || !alphanumerique(ch2) || !alpha1(ch3)) {
    alert("Vérifier votre mail SVP");
    return false;
  }

  if (psw.length < 6) {
    alert("mot de passe invalide");
    return false;
  }
  let nbchiffre = 0;
  for (let i = 0; i < psw.length; i++) {
    if (numerique(psw[i])) {
      nbchiffre++;
    }
  }
  if (nbchiffre == 0) {
    alert("mot de passe invalide");
    return false;
  }
  if (cpsw != psw) {
    alert("confirmer votre mot de passe");
    return false;
  }
  if (!conditions) {
    alert("cochage obligatoire");
    return false;
  }
}

//-----------------------------------------------------------------
function alpha(ch) {
  ch = ch.toUpperCase();
  for (let i = 0; i < ch.length; i++) {
    if ((ch[i] < "A" || ch[i] > "Z") & (ch[i] != " ")) {
      return false;
    }
  }
  return true;
}
//-----------------------------------------------------------------
function numerique(ch) {
  for (let i = 0; i < ch.length; i++) {
    if (ch[i] < "0" || ch[i] > "9") {
      return false;
    }
  }
  return true;
}
