// fonction alphabetique sans espace
function alpha1(ch) {
  ch = ch.toUpperCase();
  for (let i = 0; i < ch.length; i++) {
    if (ch[i] < "A" || ch[i] > "Z") {
      return false;
    }
  }
  return true;
}
//-----------------------------------------------
function alphanumerique(ch) {
  ch = ch.toLowerCase();
  const car = "azertyuiopqsdfghjklmwxcvbn0123456789";
  for (let i = 0; i < ch.length; i++) {
    if (car.indexOf(ch[i]) == -1) {
      return false;
    }
  }
  return true;
}
function date() {
  const dateac = document.getElementById("dateac");
  const date = new Date();
  const jour = [
    "Dimanche",
    "Lundi",
    "Mardi",
    "Mercredi",
    "Jeudi",
    "Vendredi",
    "Samedi",
  ];
  const mois = [
    "Janvier",
    "Feverie",
    "Mars",
    "Avril",
    "Mai",
    "juin",
    "Juilliet",
    "Aout",
    "Septembre",
    "Octobre",
    "Decembre",
  ];
  const today =
    jour[date.getDay()] +
    " " +
    date.getDate() +
    " " +
    mois[date.getMonth()] +
    " " +
    date.getFullYear();
  dateac.innerHTML = today;
}

function verif2() {
  
  const enfant = document.getElementById("enfant").checked;
  const adult = document.getElementById("adult").checked;
  const m12 = document.getElementById("12mois").checked;
  const m6 = document.getElementById("6mois").checked;
  const extra = document.getElementById("extra").selectedIndex;
  const promo = document.getElementById("red").checked;
  let total = 0;
  const np = prompt("saisie votre nom et prenom svp !!!!!");

  if (m12 & adult) {
    total = 900;
  }
  if (m6 & adult) {
    total = 500;
  }
  if (m12 & enfant) {
    total = 700;
  }
  if (m6 & enfant) {
    total = 400;
  }

  if (extra == 1) {
    total = total + 150;
  } else if (extra == 2) {
    total = total + 250;
  }
  if (promo) {
    total = total - total * 0.2;
  }

  document.write("bienvenu Mr/Mme :" + np + "votre abonnement vous couterait " + total + "Dt" );
}

